static const bsp_io_port_pin_t leds[4] = { LED_A, LED_B, LED_C, LED_D }; static volatile bool restart = false; static volatile bool paused  = false;

/* Switch 1 (D2, IRQ6): start over. Switch 2 (D8, IRQ4): pause / resume. */
void restart_callback(external_irq_callback_args_t *p_args) { (void) p_args; restart = true; }

