static void show(uint8_t value) { for (int i = 0; i < 4; i++) { R_IOPORT_PinWrite(&g_ioport_ctrl, leds[i], (value & (1U << (3 - i))) ? BSP_IO_LEVEL_HIGH : BSP_IO_LEVEL_LOW);
} }

/* Walks the combinations of the remaining LEDs: off first, then on. Returns false when switch 1 asked to start over. */
static bool play(uint8_t value, int led) { if (4 == led) { show(value);
        /* 0.1 s in 10 ms steps, so a pause or a restart takes effect at once. */
for (int step = 0; step < 10; step++) { R_BSP_SoftwareDelay(10, BSP_DELAY_UNITS_MILLISECONDS); while (paused && !restart) { } if (restart) { return false; } } return true;
